61	            color: var(--text-color);
62	        }
63	
64	        a {
65	            color: var(--primary-color);
66	            transition: all 0.2s;
67	            text-decoration-thickness: 2px;
68	            text-underline-offset: 4px;
69	        }
70	
71	        a:hover {
72	            opacity: 0.85;
73	            text-decoration: underline;
74	        }
75	
76	        a:focus-visible,
77	        button:focus-visible {
