96	
97	        .header-container {
98	            max-width: 1200px;
99	            margin: 0 auto;
100	            padding: 0 20px;
101	            display: flex;
102	            justify-content: space-between;
103	            align-items: center;
104	            flex-wrap: wrap;
105	            gap: 1rem;
106	        }
107	
108	        .menu-toggle {
109	            display: none;
110	            background: none;
111	            border: none;
112	            color: white;
113	            font-size: 1.5rem;
114	            cursor: pointer;
115	            padding: 0.5rem;
116	            transition: transform 0.2s;
117	            min-width: 44px;
118	            min-height: 44px;
119	        }
120	
121	        .menu-toggle:hover {
122	            transform: scale(1.1);
123	        }
124	
125	        .menu-toggle:active {
126	            transform: scale(0.95);
127	        }
128	
129	        .menu-toggle:focus-visible {
130	            outline: 2px solid white;
131	            outline-offset: 4px;
132	        }
133	
134	        header {
135	            background: var(--primary-gradient);
136	            color: white;
137	            padding: 2rem 20px;
138	            box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
139	        }
140	
141	        header h1 {
142	            margin: 0;
143	            font-size: 2.5rem;
144	            font-weight: 600;
145	        }
146	
147	        header nav ul {
148	            list-style: none;
149	            display: flex;
150	            gap: 2rem;
151	            margin: 0;
152	            padding: 0;
153	        }
154	
155	        header nav li a {
