168	        }
169	
170	        header nav li a:focus-visible {
171	            outline: 2px solid white;
172	            outline-offset: 4px;
173	            background-color: rgba(255, 255, 255, 0.15);
174	        }
175	
176	        main {
177	            max-width: 1200px;
178	            margin: 0 auto;
179	            padding: 40px 20px;
180	        }
181	
182	        article {
183	            margin-bottom: 3rem;
184	        }
185	
186	        h2 {
187	            color: var(--primary-color);
188	            margin-bottom: 1rem;
189	            font-size: 1.8rem;
190	        }
191	
192	        p {
193	            margin-bottom: 1rem;
194	            font-size: 1.05rem;
195	            line-height: 1.8;
196	        }
197	
198	        .cta-button {
199	            display: inline-flex;
200	            align-items: center;
201	            justify-content: center;
202	            gap: 0.5rem;
203	            background: var(--primary-gradient);
204	            color: white;
205	            padding: 0.875rem 2rem;
206	            border: none;
207	            border-radius: 8px;
208	            font-size: 1rem;
209	            font-weight: 600;
210	            cursor: pointer;
211	            text-decoration: none;
212	            transition: all 0.3s ease;
213	            box-shadow: 0 4px 12px rgba(102, 126, 234, 0.3);
214	            position: relative;
215	            overflow: hidden;
216	            min-height: 44px;
217	            min-width: 44px;
218	        }
219	
220	        .cta-button:hover:not(:disabled) {
221	            transform: translateY(-3px);
222	            box-shadow: 0 16px 40px rgba(102, 126, 234, 0.5);
223	        }
224	
225	        .cta-button:active:not(:disabled) {
226	            transform: translateY(-1px);
227	            box-shadow: 0 8px 20px rgba(102, 126, 234, 0.4);
228	        }
229	
230	        .cta-button:focus-visible {
231	            outline: 3px solid rgba(102, 126, 234, 0.8);
232	            outline-offset: 2px;
233	            box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.2), 0 12px 24px rgba(102, 126, 234, 0.4);
