525	        }
526	
527	        input[type="text"]:valid:not(:placeholder-shown),
528	        input[type="email"]:valid:not(:placeholder-shown) {
529	            border-color: var(--success-color);
530	        }
531	
532	        .field-error {
533	            color: var(--error-color);
534	            font-size: 0.875rem;
535	            margin-top: 0.5rem;
536	            display: none;
537	            font-weight: 500;
538	            padding: 0.5rem 0.75rem;
539	            background-color: rgba(231, 76, 60, 0.1);
540	            border-left: 3px solid var(--error-color);
541	            border-radius: 4px;
542	        }
543	
544	        .field-error.show {
545	            display: block;
546	            animation: slideDown 0.2s ease-out;
547	        }
