989	    <script>
990	        document.addEventListener('DOMContentLoaded', function() {
991	            document.getElementById('year').textContent = new Date().getFullYear();
992	
993	            const menuToggle = document.querySelector('.menu-toggle');
994	            const navMenu = document.getElementById('nav-menu');
995	
996	            if (menuToggle) {
997	                const isDesktop = () => window.innerWidth > 768;
998	
999	                const updateMenuVisibility = () => {
1000	                    if (isDesktop()) {
1001	                        navMenu.removeAttribute('hidden');
1002	                        menuToggle.setAttribute('aria-expanded', 'true');
1003	                    } else {
1004	                        navMenu.setAttribute('hidden', '');
1005	                        menuToggle.setAttribute('aria-expanded', 'false');
1006	                    }
1007	                };
1008	
1009	                const closeMenu = () => {
1010	                    if (!isDesktop()) {
1011	                        menuToggle.setAttribute('aria-expanded', 'false');
1012	                        navMenu.setAttribute('hidden', '');
1013	                        menuToggle.focus();
1014	                    }
1015	                };
1016	
1017	                updateMenuVisibility();
1018	                window.addEventListener('resize', updateMenuVisibility);
1019	
1020	                menuToggle.addEventListener('click', function() {
1021	                    if (!isDesktop()) {
1022	                        const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';
1023	                        menuToggle.setAttribute('aria-expanded', !isExpanded);
1024	                        navMenu.toggleAttribute('hidden');
1025	                    }
1026	                });
1027	
1028	                document.addEventListener('keydown', (e) => {
1029	                    if (e.key === 'Escape' && menuToggle.getAttribute('aria-expanded') === 'true') {
1030	                        closeMenu();
1031	                    }
1032	                });
1033	
1034	                const navLinks = navMenu.querySelectorAll('a');
1035	                navLinks.forEach(link => {
1036	                    link.addEventListener('click', closeMenu);
1037	                });
1038	            }
1039	
1040	            const learnMoreBtn = document.getElementById('learn-more-btn');
1041	            if (learnMoreBtn) {
1042	                learnMoreBtn.addEventListener('click', function() {
1043	                    const getStartedSection = document.getElementById('get-started');
1044	                    if (getStartedSection) {
1045	                        getStartedSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
1046	                        document.getElementById('name').focus();
1047	                    }
1048	                });
1049	            }
1050	
1051	            const contactForm = document.getElementById('contact-form');
1052	            if (contactForm) {
1053	                const showError = (field, message) => {
1054	                    const fieldGroup = field.closest('.form-group');
1055	                    const error = fieldGroup.querySelector('.field-error');
1056	                    if (error) {
1057	                        error.classList.add('show');
1058	                        error.textContent = message;
1059	                        error.setAttribute('role', 'alert');
1060	                    }
1061	                    field.setAttribute('aria-invalid', 'true');
1062	                };
1063	
1064	                const clearError = (field) => {
1065	                    const fieldGroup = field.closest('.form-group');
1066	                    const error = fieldGroup.querySelector('.field-error');
1067	                    if (error) {
1068	                        error.classList.remove('show');
1069	                        error.textContent = '';
1070	                    }
1071	                    field.setAttribute('aria-invalid', 'false');
1072	                };
1073	
1074	                const validateField = (field) => {
1075	                    if (!field) return false;
1076	                    const value = field.value.trim();
1077	
1078	                    if (!value) {
1079	                        const label = field.labels?.[0]?.textContent?.trim() || 'This field';
1080	                        showError(field, `${label} is required`);
1081	                        return false;
1082	                    }
1083	
1084	                    if (!field.checkValidity()) {
1085	                        let message = 'Invalid input';
1086	                        if (field.type === 'email') {
1087	                            message = 'Please enter a valid email address (e.g., name@domain.com)';
1088	                        } else if (field.id === 'name') {
1089	                            if (field.value.length < 2) {
1090	                                message = 'Please enter at least 2 characters';
1091	                            } else {
1092	                                message = 'Please use only letters and spaces (no numbers or symbols)';
1093	                            }
1094	                        } else if (field.id === 'message') {
1095	                            if (field.value.length < 10) {
1096	                                message = `Message must be at least 10 characters (currently ${field.value.length})`;
1097	                            } else if (field.value.length > 1000) {
1098	                                message = `Message cannot exceed 1000 characters (currently ${field.value.length})`;
1099	                            } else {
1100	                                message = 'Please provide a valid message';
1101	                            }
1102	                        }
1103	                        showError(field, message);
1104	                        return false;
1105	                    }
1106	
1107	                    clearError(field);
1108	                    return true;
1109	                };
1110	
1111	                const messageField = document.getElementById('message');
1112	                const messageCounter = document.getElementById('message-counter');
1113	
1114	                const updateMessageCounter = () => {
1115	                    if (messageCounter) {
1116	                        messageCounter.textContent = `${messageField.value.length} / 1000`;
1117	                    }
1118	                };
1119	
1120	                if (messageField && messageCounter) {
1121	                    updateMessageCounter();
1122	                    messageField.addEventListener('input', updateMessageCounter);
1123	                }
1124	
1125	                const inputs = contactForm.querySelectorAll('input, textarea');
1126	                inputs.forEach(input => {
1127	                    input.addEventListener('blur', () => validateField(input));
1128	                    input.addEventListener('input', () => {
1129	                        if (input.getAttribute('aria-invalid') === 'true') {
1130	                            validateField(input);
1131	                        }
1132	                    });
1133	                });
1134	
1135	                let isSubmitting = false;
1136	
1137	                contactForm.addEventListener('submit', function(e) {
1138	                    e.preventDefault();
1139	
1140	                    if (isSubmitting) return;
1141	
1142	                    let isValid = true;
1143	                    const feedback = document.getElementById('form-feedback');
1144	                    feedback.className = 'form-feedback';
1145	                    feedback.textContent = '';
1146	
1147	                    inputs.forEach(input => {
1148	                        if (!validateField(input)) isValid = false;
1149	                    });
1150	
1151	                    if (!isValid) {
1152	                        feedback.className = 'form-feedback error';
1153	                        feedback.textContent = 'Please correct the errors above and try again.';
1154	                        feedback.setAttribute('role', 'alert');
1155	                        feedback.setAttribute('aria-live', 'assertive');
1156	                        const firstError = contactForm.querySelector('[aria-invalid="true"]');
1157	                        if (firstError && firstError.focus) {
1158	                            firstError.focus();
1159	                        }
1160	                        return;
1161	                    }
1162	
1163	                    const submitBtn = document.getElementById('submit-btn');
1164	                    isSubmitting = true;
1165	                    submitBtn.disabled = true;
1166	                    submitBtn.classList.add('loading');
1167	                    const originalHTML = submitBtn.innerHTML;
1168	                    const originalAriaLabel = submitBtn.getAttribute('aria-label');
1169	                    submitBtn.innerHTML = '<span class="spinner" aria-hidden="true"></span>Sending...';
1170	                    submitBtn.setAttribute('aria-label', 'Sending message, please wait');
1171	
1172	                    const formData = new FormData(contactForm);
1173	                    const endpoint = contactForm.getAttribute('data-endpoint') || '/contact';
1174	                    const controller = new AbortController();
1175	                    const timeoutId = setTimeout(() => controller.abort(), 10000);
1176	
1177	                    fetch(endpoint, {
1178	                        method: 'POST',
1179	                        body: formData,
1180	                        signal: controller.signal
1181	                    })
1182	                    .then(response => {
1183	                        if (!response.ok) {
1184	                            throw new Error(`Server error: ${response.status}`);
1185	                        }
1186	                        return response;
1187	                    })
1188	                    .then(() => {
1189	                        feedback.className = 'form-feedback success';
1190	                        feedback.textContent = 'Thank you for your message! We will be in touch soon.';
1191	                        feedback.setAttribute('role', 'status');
1192	                        feedback.setAttribute('aria-live', 'polite');
1193	                        contactForm.reset();
1194	                        inputs.forEach(input => {
1195	                            clearError(input);
1196	                            input.setAttribute('aria-invalid', 'false');
1197	                        });
1198	                        updateMessageCounter();
1199	                    })
1200	                    .catch(error => {
1201	                        feedback.className = 'form-feedback error';
1202	                        feedback.setAttribute('role', 'alert');
1203	                        feedback.setAttribute('aria-live', 'assertive');
1204	                        if (error.name === 'AbortError') {
1205	                            feedback.textContent = 'Request took too long. Please check your connection and try again.';
1206	                        } else if (error instanceof TypeError) {
1207	                            feedback.textContent = 'Unable to connect. Please check your internet connection and try again.';
1208	                        } else {
1209	                            feedback.textContent = 'Something went wrong. Please try again in a moment.';
1210	                            console.error('Form submission error:', error);
1211	                        }
1212	                    })
1213	                    .finally(() => {
1214	                        clearTimeout(timeoutId);
1215	                        isSubmitting = false;
1216	                        submitBtn.disabled = false;
1217	                        submitBtn.classList.remove('loading');
1218	                        submitBtn.innerHTML = originalHTML;
1219	                        if (originalAriaLabel) {
1220	                            submitBtn.setAttribute('aria-label', originalAriaLabel);
1221	                        }
1222	                        requestAnimationFrame(() => {
1223	                            feedback.scrollIntoView({ behavior: 'smooth', block: 'center' });
1224	                            feedback.focus();
1225	                        });
1226	                    });
1227	                });
1228	            }
1229	        });
1230	    </script>
