fetch(endpoint, {
    method: 'POST',
    body: formData,
    signal: controller.signal
})
.then(response => {
    if (!response.ok) {
        throw new Error(`Server error: ${response.status}`);
    }
    return response;
})
.then(() => {
    feedback.className = 'form-feedback success';
    feedback.textContent = 'Thank you for your message! We will be in touch soon.';
    feedback.setAttribute('role', 'status');
    feedback.setAttribute('aria-live', 'polite');
    contactForm.reset();
    inputs.forEach(input => {
        clearError(input);
        input.setAttribute('aria-invalid', 'false');
    });
    updateMessageCounter();
})
.catch(error => {
    feedback.className = 'form-feedback error';
    feedback.setAttribute('role', 'alert');
    feedback.setAttribute('aria-live', 'assertive');
    if (error.name === 'AbortError') {
        feedback.textContent = 'Request took too long. Please check your connection and try again.';
    } else if (error instanceof TypeError) {
        feedback.textContent = 'Unable to connect. Please check your internet connection and try again.';
    } else {
        feedback.textContent = 'Something went wrong. Please try again in a moment.';
        console.error('Form submission error:', error);
    }
})

